package main
import("strings";"strconv")
var _=strings.Compare
var _=strconv.Itoa
func solve(x map[string]any)any{s:=x["text"].(string);n:=int(x["n"].(float64));out:=[]any{};for i:=0;i<len(s);i+=n{end:=i+n;if end>len(s){end=len(s)};out=append(out,s[i:end])};return out}

