package main
import("encoding/json";"testing";"reflect")
func TestContractBoundaries(t *testing.T){var rows [][]json.RawMessage;if e:=json.Unmarshal([]byte(`[[{"text": "abcde", "n": 2}, ["ab", "cd", "e"]], [{"text": "a", "n": 8}, ["a"]], [{"text": "xyz", "n": 1}, ["x", "y", "z"]]]`),&rows);e!=nil{t.Fatal(e)};for _,row:=range rows{var input map[string]any;var expected,actual any;json.Unmarshal(row[0],&input);json.Unmarshal(row[1],&expected);b,e:=json.Marshal(solve(input));if e!=nil{t.Fatal(e)};json.Unmarshal(b,&actual);if !reflect.DeepEqual(actual,expected){t.Fatalf("got %v expected %v",actual,expected)}}}
